import { useEffect, useState } from "react";
import { RADIUS, SPACE, TYPE, useThemed } from "../theme.js";
import { Modal } from "./Modal.jsx";
import { t, tn } from "../i18n.js";

// The open-source packages Budget Ctrl is built from, with their licence
// texts. The list is generated by scripts/licenses.js and is large, so it
// loads only when this opens.
export function LicensesModal({ onClose }) {
  const { theme, s } = useThemed();
  const [data, setData] = useState(null);
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(null);

  useEffect(() => {
    let alive = true;
    import("../licenses/third-party.json").then((m) => { if (alive) setData(m.default); });
    return () => { alive = false; };
  }, []);

  const q = query.trim().toLowerCase();
  const shown = data ? data.packages.filter((p) => !q || `${p.name} ${p.license}`.toLowerCase().includes(q)) : [];

  return (
    <Modal title={t("Open-source licences")} onClose={onClose} width={720}>
      <div style={{ ...TYPE.caption, color: theme.textMuted, lineHeight: 1.5, marginBottom: SPACE.md }}>
        {t("Budget Ctrl is built on these open-source packages. Their licences ask for these notices to come with the app. Some packages are only used on other systems, or while the app is being built.")}
      </div>
      <input style={{ ...s.input, marginBottom: SPACE.sm }} placeholder={t("Search packages")} value={query}
        onChange={(e) => { setQuery(e.target.value); setOpen(null); }} />
      {!data ? <div style={s.emptySmall}>{t("Loading...")}</div> : (
        <>
          <div style={{ ...TYPE.caption, color: theme.textFaint, margin: `${SPACE.xs}px 0` }}>{tn(shown.length, "{n} package", "{n} packages")}</div>
          {shown.length === 0 && <div style={s.emptySmall}>{t("No packages match.")}</div>}
          {shown.map((p) => {
            const key = `${p.source}:${p.name}@${p.version}`;
            const expanded = open === key;
            return (
              <div key={key} style={{ borderBottom: `1px solid ${theme.cardBorder}` }}>
                <button onClick={() => setOpen(expanded ? null : key)} aria-expanded={expanded}
                  style={{ ...s.linkBtn, display: "flex", width: "100%", justifyContent: "space-between", gap: SPACE.md, padding: `${SPACE.sm}px 0`, color: theme.text, textAlign: "left" }}>
                  <span style={{ overflow: "hidden", textOverflow: "ellipsis" }}>{p.name} <span style={{ color: theme.textFaint }}>{p.version}</span></span>
                  <span style={{ color: theme.textMuted, whiteSpace: "nowrap" }}>{p.license}</span>
                </button>
                {expanded && (
                  <div style={{ paddingBottom: SPACE.md }}>
                    <div style={{ ...TYPE.caption, color: theme.textMuted, marginBottom: SPACE.xs, userSelect: "text", wordBreak: "break-all" }}>
                      {t("Source code: {url}", { url: p.url })}{p.repository ? ` · ${p.repository}` : ""}
                    </div>
                    {p.texts.map((i) => (
                      <pre key={i} style={{ ...TYPE.caption, fontSize: 11, lineHeight: 1.45, whiteSpace: "pre-wrap", wordBreak: "break-word", userSelect: "text",
                                            background: theme.bg, border: `1px solid ${theme.cardBorder}`, borderRadius: RADIUS.md, padding: SPACE.sm,
                                            margin: `${SPACE.xs}px 0 0`, maxHeight: 260, overflowY: "auto", fontFamily: "ui-monospace, Consolas, monospace" }}>
                        {data.texts[i]}
                      </pre>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </>
      )}
    </Modal>
  );
}
